INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 27, 'theory', 'Квиз: fork, exec, mmap и ioctl');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 0, 'Родитель запустил ребёнка через fork, ребёнок завершился, а родитель продолжает работать и никогда не вызывает wait. Что покажет ps?', '["Ничего: ядро сразу удаляет завершившийся процесс", "Ребёнка в состоянии S, он ждёт родителя", "Ребёнка в состоянии Z, помеченного defunct: зомби", "Ребёнка уже усыновил процесс номер один, и он исчез"]', 2, 'Запись о завершившемся процессе хранится, пока родитель не заберёт статус вызовом wait. Усыновление касается случая, когда умирает родитель, а здесь он жив; убить зомби нельзя, надо чинить родителя.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 1, 'Ребёнок вызывает exit(300). Что вернёт WEXITSTATUS(status) в родителе?', '["300", "44", "255", "0"]', 1, 'Родителю достаются только младшие 8 бит кода выхода: 300 mod 256 даёт 44.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 2, 'В конвейере a | b процесс b читает из канала и не завершается после того, как a закончил и вышел. Какая причина самая вероятная?', '["Процесс a стал зомби, поэтому канал не закрыт", "У канала переполнен буфер размером 4096 байт", "b вызвал exec и потерял дескриптор ноль", "Где-то остался открытый записывающий конец канала, например в родителе, и читатель не видит EOF"]', 3, 'EOF приходит, только когда закрыты все записывающие концы. Забытая копия в родителе или в другом ребёнке держит канал открытым. Зомби и размер буфера на это не влияют.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 3, 'Родитель создал mmap с флагами MAP_PRIVATE | MAP_ANONYMOUS, затем сделал fork, и ребёнок записал в отображение число. Что увидит родитель?', '["Прежнее содержимое: запись ребёнка попала в его собственную копию страницы", "Новое число: отображения всегда общие после fork", "Сигнал SIGBUS при чтении", "Ошибку EINVAL при чтении"]', 0, 'MAP_PRIVATE даёт копирование при записи: после fork у каждого процесса своя копия изменённой страницы. Для обмена нужен MAP_SHARED.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 27, 4, 'Запрос определён как _IOW(''k'', 2, int). Что это значит и каким будет его размер в поле номера?', '["Ядро пишет int пользователю, размер поля 2", "Нет данных, размер поля 0", "Пользователь передаёт int ядру, размер поля 4 (на обычной платформе)", "Данные идут в обе стороны, размер поля 8"]', 2, 'W означает запись со стороны пользователя: ядро читает аргумент. Размер берётся от типа int, обычно 4 байта; число 2 это номер команды, а не размер.');
